package com.hostelmanagement.paymentmethods;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

/** Plain SQL for {@code payment_method_settings}: the encrypted column is bytes and the scope key is generated by MySQL. */
@Repository
public class PaymentMethodRepository {

    public record Row(Long ownerId, Long hostelId, boolean acceptsCash, boolean acceptsUpi, String upiId, String upiPayeeName,
                      Long qrFileId, boolean acceptsBank, String holder, String bankName, String branch, String ifsc,
                      byte[] accountEnc, String last4, boolean acceptsOnline, String instructions, Instant updatedAt) {

        /** What an owner who never configured anything gets: cash and online payments, nothing else. */
        public static Row defaults(Long ownerId, Long hostelId) {
            return new Row(ownerId, hostelId, true, false, null, null, null, false, null, null, null, null, null, null, true, null, null);
        }
    }

    private final JdbcTemplate jdbc;

    public PaymentMethodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Optional<Row> find(Long ownerId, Long hostelId) {
        List<Row> rows = jdbc.query("SELECT * FROM payment_method_settings WHERE owner_id = ? AND hostel_key = ?",
                (rs, i) -> new Row(rs.getLong("owner_id"), (Long) rs.getObject("hostel_id"), rs.getBoolean("accepts_cash"),
                        rs.getBoolean("accepts_upi"), rs.getString("upi_id"), rs.getString("upi_payee_name"),
                        (Long) rs.getObject("upi_qr_file_id"), rs.getBoolean("accepts_bank_transfer"), rs.getString("bank_account_holder"),
                        rs.getString("bank_name"), rs.getString("bank_branch"), rs.getString("bank_ifsc"),
                        rs.getBytes("bank_account_number_enc"), rs.getString("bank_account_last4"), rs.getBoolean("accepts_online"),
                        rs.getString("instructions"), rs.getTimestamp("updated_at").toInstant()),
                ownerId, hostelId == null ? 0L : hostelId);
        return rows.stream().findFirst();
    }

    public void save(Row r, Long updatedBy) {
        Timestamp now = Timestamp.from(Instant.now());
        jdbc.update("""
                INSERT INTO payment_method_settings (owner_id, hostel_id, accepts_cash, accepts_upi, upi_id, upi_payee_name,
                    upi_qr_file_id, accepts_bank_transfer, bank_account_holder, bank_name, bank_branch, bank_ifsc,
                    bank_account_number_enc, bank_account_last4, accepts_online, instructions, updated_by, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON DUPLICATE KEY UPDATE accepts_cash = VALUES(accepts_cash), accepts_upi = VALUES(accepts_upi),
                    upi_id = VALUES(upi_id), upi_payee_name = VALUES(upi_payee_name), upi_qr_file_id = VALUES(upi_qr_file_id),
                    accepts_bank_transfer = VALUES(accepts_bank_transfer), bank_account_holder = VALUES(bank_account_holder),
                    bank_name = VALUES(bank_name), bank_branch = VALUES(bank_branch), bank_ifsc = VALUES(bank_ifsc),
                    bank_account_number_enc = VALUES(bank_account_number_enc), bank_account_last4 = VALUES(bank_account_last4),
                    accepts_online = VALUES(accepts_online), instructions = VALUES(instructions),
                    updated_by = VALUES(updated_by), updated_at = VALUES(updated_at)""",
                r.ownerId(), r.hostelId(), r.acceptsCash(), r.acceptsUpi(), r.upiId(), r.upiPayeeName(), r.qrFileId(), r.acceptsBank(),
                r.holder(), r.bankName(), r.branch(), r.ifsc(), r.accountEnc(), r.last4(), r.acceptsOnline(), r.instructions(),
                updatedBy, now, now);
    }

    public int delete(Long ownerId, Long hostelId) {
        return jdbc.update("DELETE FROM payment_method_settings WHERE owner_id = ? AND hostel_key = ?", ownerId,
                hostelId == null ? 0L : hostelId);
    }
}
